import logging
from pathlib import Path
from typing import Optional, List, Dict, Any, Set
import re # Added for calculate_word_jaccard_index

import joblib
import pandas as pd
import numpy as np

from .. import config
from ..models import FolderInfo, FolderComparisonResult

logger = logging.getLogger(__name__)

class MLSimilarityModel:
    # This list is derived from the CSV header provided in the prompt,
    # and should match the features generated by create_ml_dataset.py
    EXPECTED_FEATURE_NAMES_ORDERED = [
        'f1_avg_bitrate', 'f2_avg_bitrate', 'diff_avg_bitrate',
        'jaccard_unique_artists', 'jaccard_unique_albums',
        'f1_generic_filename_score', 'f2_generic_filename_score', 'diff_generic_filename_score',
        'f1_generic_title_score', 'f2_generic_title_score', 'diff_generic_title_score',
        'f1_avg_duration', 'f2_avg_duration', 'diff_avg_duration',
        'f1_std_duration', 'f2_std_duration', 'diff_std_duration',
        'f1_min_duration', 'f2_min_duration', 'diff_min_duration',
        'f1_max_duration', 'f2_max_duration', 'diff_max_duration',
        'f1_total_duration', 'f2_total_duration', 'diff_total_duration', 'ratio_total_duration',
        'f1_std_bitrate', 'f2_std_bitrate', 'diff_std_bitrate',
        'f1_min_bitrate', 'f2_min_bitrate', 'diff_min_bitrate',
        'f1_max_bitrate', 'f2_max_bitrate', 'diff_max_bitrate',
        'f1_avg_other_file_size_bytes', 'f2_avg_other_file_size_bytes', 'diff_avg_other_file_size_bytes',
        'f1_total_other_file_size_bytes', 'f2_total_other_file_size_bytes', 'diff_total_other_file_size_bytes', 'ratio_total_other_file_size_bytes',
        'f1_parent_folder_name_len', 'f2_parent_folder_name_len', 'diff_parent_folder_name_len', 'parent_folder_names_match', 'jaccard_parent_folder_names',
        'f1_quality_score', 'f2_quality_score', 'diff_quality_score',
        'f1_hebrew_metadata_ratio', 'f2_hebrew_metadata_ratio', 'diff_hebrew_metadata_ratio',
        'f1_metadata_completeness_ratio', 'f2_metadata_completeness_ratio', 'diff_metadata_completeness_ratio',
        'f1_lossless_ratio', 'f2_lossless_ratio', 'diff_lossless_ratio',
        'f1_lyrics_ratio', 'f2_lyrics_ratio', 'diff_lyrics_ratio',
        'f1_num_other_files', 'f2_num_other_files', 'diff_num_other_files', 'ratio_num_other_files', 'jaccard_other_file_names',
        'other_files_common_hash_ratio', 'other_files_common_avg_size_similarity',
        'comp_file_hash_similarity', 'comp_file_size_similarity', 'comp_filename_similarity', 'comp_title_similarity', 'comp_album_similarity', 'comp_artist_similarity', 'comp_albumartist_similarity', 'comp_folder_name_similarity', 'comp_album_art_hash_similarity', 'comp_duration_similarity', 'comp_other_files_similarity',
        'comp_avg_add_meta_similarity', 'comp_count_high_add_meta_similarity',
        'comp_add_meta_sim_length', 'comp_add_meta_sim_date', 'comp_add_meta_sim_tracknumber', 'comp_add_meta_sim_genre', 'comp_add_meta_sim_media', 'comp_add_meta_sim_composer', 'comp_add_meta_sim_encodedby', 'comp_add_meta_sim_discnumber', 'comp_add_meta_sim_organization', 'comp_add_meta_sim_grouping', 'comp_add_meta_sim_bpm', 'comp_add_meta_sim_copyright', 'comp_add_meta_sim_barcode', 'comp_add_meta_sim_conductor', 'comp_add_meta_sim_website', 'comp_add_meta_sim_version', 'comp_add_meta_sim_compilation', 'comp_add_meta_sim_titlesort', 'comp_add_meta_sim_albumsort', 'comp_add_meta_sim_lyricist', 'comp_add_meta_sim_isrc', 'comp_add_meta_sim_author', 'comp_add_meta_sim_originaldate'
    ]

    # Specific additional metadata tags the model expects, derived from the CSV header
    _EXPECTED_ADD_META_SIM_TAGS = [
        'length', 'date', 'tracknumber', 'genre', 'media', 'composer', 'encodedby', 
        'discnumber', 'organization', 'grouping', 'bpm', 'copyright', 'barcode', 
        'conductor', 'website', 'version', 'compilation', 'titlesort', 'albumsort', 
        'lyricist', 'isrc', 'author', 'originaldate'
    ]


    def __init__(self, model_path: Path = config.ML_MODEL_FILE):
        self.model_path = model_path
        self.resolved_model_path: Optional[Path] = None
        self.model = None
        self.model_loaded = False
        self._load_model()

    def _load_model(self):
        try:
            candidate_paths = [self.model_path, config.SIMILARITY_MODEL_FALLBACK_FILE]
            existing_path = next((path for path in candidate_paths if path.exists()), None)
            if existing_path is None:
                logger.warning(
                    "ML model file not found at any known location: %s. ML-based similarity will be disabled.",
                    ", ".join(str(path) for path in candidate_paths),
                )
                return
            self.resolved_model_path = existing_path
            self.model = joblib.load(existing_path)
            self.model_loaded = True
            logger.info(f"ML similarity model loaded successfully from: {existing_path}")
        except Exception as e:
            logger.error(f"Error loading ML similarity model from {self.model_path}: {e}", exc_info=True)
            self.model = None
            self.model_loaded = False

    def _calculate_jaccard_index(self, set1: Set[Any], set2: Set[Any]) -> float:
        if not isinstance(set1, set) or not isinstance(set2, set):
            logger.warning(f"Jaccard index calculation received non-set types: {type(set1)}, {type(set2)}")
            return 0.0
        if not set1 and not set2:
            return 1.0
        intersection_len = len(set1.intersection(set2))
        union_len = len(set1.union(set2))
        return intersection_len / union_len if union_len > 0 else 0.0

    def _calculate_word_jaccard_index(self, str1: Optional[str], str2: Optional[str]) -> float:
        if not str1 and not str2: return 1.0
        if not str1 or not str2: return 0.0

        words1 = set(re.findall(r'\w+', str1.lower()))
        words2 = set(re.findall(r'\w+', str2.lower()))
        return self._calculate_jaccard_index(words1, words2)

    def _ml_calculate_folder_stats(self, folder_info: FolderInfo) -> Dict[str, float]:
        # This is a copy of _calculate_folder_stats from create_ml_dataset.py
        stats: Dict[str, Optional[float]] = {
            "avg_duration": None, "std_duration": None, "min_duration": None, "max_duration": None, "total_duration": None,
            "std_bitrate": None, "min_bitrate": None, "max_bitrate": None,
            "avg_other_file_size_bytes": None, "total_other_file_size_bytes": None,
        }
        if not folder_info.files and not folder_info.other_files:
            return {k: 0.0 for k in stats.keys()}


        if folder_info.files:
            durations = [f.duration for f in folder_info.files if f.duration is not None and f.duration > 0]
            bitrates = [f.bitrate for f in folder_info.files if f.bitrate is not None and f.bitrate > 0]

            if durations:
                stats["avg_duration"] = float(np.mean(durations))
                stats["std_duration"] = float(np.std(durations)) if len(durations) > 1 else 0.0
                stats["min_duration"] = float(np.min(durations))
                stats["max_duration"] = float(np.max(durations))
                stats["total_duration"] = float(np.sum(durations))

            if bitrates:
                stats["std_bitrate"] = float(np.std(bitrates)) if len(bitrates) > 1 else 0.0
                stats["min_bitrate"] = float(np.min(bitrates))
                stats["max_bitrate"] = float(np.max(bitrates))


        if folder_info.other_files:
            other_file_sizes = [f.get('size_bytes', 0) for f in folder_info.other_files if f.get('size_bytes', 0) > 0]
            if other_file_sizes:
                stats["avg_other_file_size_bytes"] = float(np.mean(other_file_sizes))
                stats["total_other_file_size_bytes"] = float(np.sum(other_file_sizes))


        final_stats: Dict[str, float] = {}
        for key in ["avg_duration", "std_duration", "min_duration", "max_duration", "total_duration",
                    "std_bitrate", "min_bitrate", "max_bitrate",
                    "avg_other_file_size_bytes", "total_other_file_size_bytes"]:
            final_stats[key] = stats.get(key, 0.0) if stats.get(key) is not None else 0.0

        return final_stats

    def _prepare_features_for_prediction(self,
                                        folder1_info: FolderInfo,
                                        folder2_info: FolderInfo,
                                        comparison_result: FolderComparisonResult) -> Optional[pd.DataFrame]:
        if not folder1_info or not folder2_info or not comparison_result:
            logger.warning("Missing data for ML feature preparation.")
            return None

        features: Dict[str, Any] = {}

        try:
            # Basic Bitrate
            f1_avg_bitrate = folder1_info.avg_bitrate if folder1_info.avg_bitrate is not None else 0.0
            f2_avg_bitrate = folder2_info.avg_bitrate if folder2_info.avg_bitrate is not None else 0.0
            features['f1_avg_bitrate'] = f1_avg_bitrate
            features['f2_avg_bitrate'] = f2_avg_bitrate
            features['diff_avg_bitrate'] = abs(f1_avg_bitrate - f2_avg_bitrate)

            # Jaccard Indices
            features['jaccard_unique_artists'] = self._calculate_jaccard_index(folder1_info.unique_artists, folder2_info.unique_artists)
            features['jaccard_unique_albums'] = self._calculate_jaccard_index(folder1_info.unique_albums, folder2_info.unique_albums)

            # Generic Scores
            f1_gen_fname_score = folder1_info.generic_filename_score if folder1_info.generic_filename_score is not None else 0.0
            f2_gen_fname_score = folder2_info.generic_filename_score if folder2_info.generic_filename_score is not None else 0.0
            features['f1_generic_filename_score'] = f1_gen_fname_score
            features['f2_generic_filename_score'] = f2_gen_fname_score
            features['diff_generic_filename_score'] = abs(f1_gen_fname_score - f2_gen_fname_score)

            f1_gen_title_score = folder1_info.generic_title_score if folder1_info.generic_title_score is not None else 0.0
            f2_gen_title_score = folder2_info.generic_title_score if folder2_info.generic_title_score is not None else 0.0
            features['f1_generic_title_score'] = f1_gen_title_score
            features['f2_generic_title_score'] = f2_gen_title_score
            features['diff_generic_title_score'] = abs(f1_gen_title_score - f2_gen_title_score)

            # Folder Stats
            folder1_stats = self._ml_calculate_folder_stats(folder1_info)
            folder2_stats = self._ml_calculate_folder_stats(folder2_info)
            for stat_key in ["avg_duration", "std_duration", "min_duration", "max_duration", "total_duration",
                             "std_bitrate", "min_bitrate", "max_bitrate",
                             "avg_other_file_size_bytes", "total_other_file_size_bytes"]:
                s1_val = folder1_stats[stat_key]
                s2_val = folder2_stats[stat_key]
                features[f'f1_{stat_key}'] = s1_val
                features[f'f2_{stat_key}'] = s2_val
                features[f'diff_{stat_key}'] = abs(s1_val - s2_val)
                if stat_key == "total_duration":
                    if s1_val == 0 and s2_val == 0: features['ratio_total_duration'] = 1.0
                    else: features['ratio_total_duration'] = min(s1_val, s2_val) / max(1.0, s1_val, s2_val)
                if stat_key == "total_other_file_size_bytes":
                    if s1_val == 0 and s2_val == 0: features['ratio_total_other_file_size_bytes'] = 1.0
                    else: features['ratio_total_other_file_size_bytes'] = min(s1_val,s2_val) / max(1.0, s1_val, s2_val)
            
            # Parent Folder Name
            f1_parent_name = folder1_info.parent_folder_name
            f2_parent_name = folder2_info.parent_folder_name
            features['f1_parent_folder_name_len'] = len(f1_parent_name) if f1_parent_name else 0
            features['f2_parent_folder_name_len'] = len(f2_parent_name) if f2_parent_name else 0
            features['diff_parent_folder_name_len'] = abs(features['f1_parent_folder_name_len'] - features['f2_parent_folder_name_len'])
            features['parent_folder_names_match'] = 1.0 if f1_parent_name and f1_parent_name == f2_parent_name else 0.0
            features['jaccard_parent_folder_names'] = self._calculate_word_jaccard_index(f1_parent_name, f2_parent_name)

            # Quality Related Fields
            quality_related_fields_map = {
                'quality_score': (folder1_info.quality_score, folder2_info.quality_score),
                'hebrew_metadata_ratio': (folder1_info.hebrew_metadata_ratio, folder2_info.hebrew_metadata_ratio),
                'metadata_completeness_ratio': (folder1_info.metadata_completeness_ratio, folder2_info.metadata_completeness_ratio),
                'lossless_ratio': (folder1_info.lossless_ratio, folder2_info.lossless_ratio),
                'lyrics_ratio': (folder1_info.lyrics_ratio, folder2_info.lyrics_ratio),
            }
            for field, (val1, val2) in quality_related_fields_map.items():
                v1 = val1 if val1 is not None else 0.0
                v2 = val2 if val2 is not None else 0.0
                features[f'f1_{field}'] = v1
                features[f'f2_{field}'] = v2
                features[f'diff_{field}'] = abs(v1 - v2)

            # Other Files Details
            f1_other_files_details: List[Dict[str, Any]] = folder1_info.other_files
            f2_other_files_details: List[Dict[str, Any]] = folder2_info.other_files
            f1_other_files_names = {f['name'] for f in f1_other_files_details}
            f2_other_files_names = {f['name'] for f in f2_other_files_details}
            features['f1_num_other_files'] = len(f1_other_files_details)
            features['f2_num_other_files'] = len(f2_other_files_details)
            features['diff_num_other_files'] = abs(features['f1_num_other_files'] - features['f2_num_other_files'])
            if max(features['f1_num_other_files'], features['f2_num_other_files']) > 0:
                features['ratio_num_other_files'] = min(features['f1_num_other_files'], features['f2_num_other_files']) / \
                                                    max(1.0, features['f1_num_other_files'], features['f2_num_other_files'])
            else: features['ratio_num_other_files'] = 1.0
            features['jaccard_other_file_names'] = self._calculate_jaccard_index(f1_other_files_names, f2_other_files_names)

            common_other_file_names = f1_other_files_names.intersection(f2_other_files_names)
            other_files_hash_match_count = 0
            other_files_size_similarity_sum = 0.0
            if common_other_file_names:
                f1_other_map = {f['name']: f for f in f1_other_files_details}
                f2_other_map = {f['name']: f for f in f2_other_files_details}
                for name in common_other_file_names:
                    of1 = f1_other_map[name]
                    of2 = f2_other_map[name]
                    if of1.get('hash') and of2.get('hash') and of1['hash'] == of2['hash']:
                        other_files_hash_match_count += 1
                    s1, s2 = of1.get('size_bytes', 0), of2.get('size_bytes', 0)
                    if s1 > 0 and s2 > 0:
                        ratio = min(s1, s2) / max(s1, s2)
                        other_files_size_similarity_sum += 1.0 if ratio >= 0.95 else ratio * ratio
                    elif s1 == 0 and s2 == 0: other_files_size_similarity_sum += 1.0
            
            num_common_other_files = len(common_other_file_names)
            features['other_files_common_hash_ratio'] = other_files_hash_match_count / num_common_other_files if num_common_other_files > 0 else 0.0
            features['other_files_common_avg_size_similarity'] = other_files_size_similarity_sum / num_common_other_files if num_common_other_files > 0 else 0.0

            # Comparison Result Scores
            sim_scores = comparison_result.similarity_scores # This is FolderComparisonResult.similarity_scores
            comp_feature_keys = [
                'file_hash', 'file_size', 'filename', 'title', 'album',
                'artist', 'albumartist', 'folder_name', 'album_art_hash', 'duration'
            ]
            for key in comp_feature_keys:
                features[f'comp_{key}_similarity'] = sim_scores.get(key, 0.0)
            features['comp_other_files_similarity'] = sim_scores.get('other_files_similarity', 0.0)
            
            add_meta_details = sim_scores.get('additional_metadata_details', {})
            if isinstance(add_meta_details, dict) and add_meta_details: # Check if dict and not empty
                features['comp_avg_add_meta_similarity'] = sum(add_meta_details.values()) / len(add_meta_details)
                features['comp_count_high_add_meta_similarity'] = sum(1 for v in add_meta_details.values() if v >= 0.8)
            else:
                features['comp_avg_add_meta_similarity'] = 0.0
                features['comp_count_high_add_meta_similarity'] = 0.0
            
            for meta_tag in self._EXPECTED_ADD_META_SIM_TAGS:
                # In comparison_result.similarity_scores, additional_metadata_details stores keys like 'length', 'date' directly.
                # The dataset feature name is 'comp_add_meta_sim_length'.
                # So, we use `meta_tag` to lookup in `add_meta_details` and construct the feature name.
                feature_name = f'comp_add_meta_sim_{meta_tag}'
                features[feature_name] = add_meta_details.get(meta_tag, 0.0) if isinstance(add_meta_details, dict) else 0.0


            # Create ordered list of feature values
            feature_values_ordered = []
            for feature_name in self.EXPECTED_FEATURE_NAMES_ORDERED:
                # All features should now be in the `features` dict.
                # Default to 0.0 if a feature was somehow missed, though ideally all are calculated.
                val = features.get(feature_name, 0.0)
                if val is None: # Ensure no None makes it to the DataFrame
                    logger.warning(f"Feature '{feature_name}' had None value for pair "
                                   f"{folder1_info.path.name} and {folder2_info.path.name}. Defaulting to 0.0.")
                    val = 0.0
                feature_values_ordered.append(val)
            
            df = pd.DataFrame([feature_values_ordered], columns=self.EXPECTED_FEATURE_NAMES_ORDERED)
            return df

        except Exception as e:
            logger.error(f"Error preparing features for ML prediction "
                         f"for pair {folder1_info.path.name} and {folder2_info.path.name}: {e}", exc_info=True)
            return None


    def predict_similarity_for_pair(self,
                                   folder1_info: FolderInfo,
                                   folder2_info: FolderInfo,
                                   comparison_result: FolderComparisonResult) -> Optional[float]:
        if not self.model_loaded or self.model is None:
            logger.debug("ML model not loaded. Skipping ML prediction.")
            return None

        features_df = self._prepare_features_for_prediction(folder1_info, folder2_info, comparison_result)

        if features_df is None:
            logger.warning(f"Feature preparation failed for ML prediction for pair: "
                           f"{folder1_info.path.name} and {folder2_info.path.name}. Skipping.")
            return None


        if features_df.isnull().values.any():
            logger.warning(f"NaN values found in features for ML prediction (pair: "
                           f"{folder1_info.path.name}, {folder2_info.path.name}). Model might behave unexpectedly or error. "
                           f"NaNs: {features_df.columns[features_df.isnull().any()].tolist()}")
            # Optionally, fill NaNs: features_df.fillna(0.0, inplace=True) if model robust to this


        try:
            prediction = self.model.predict(features_df)

            ml_score = float(prediction[0]) # Prediction is usually a numpy array

            # Clip the score to be between 0 and 100, as similarity scores usually are.
            # The model's output range might vary based on its training target (e.g. 0-5, 0-100, etc.)
            # Assuming the model was trained to output scores in 0-100 range.
            # If it was, e.g. 0-5 (like in some dataset labels), it would need scaling: ml_score * 20
            # For now, we just clip. If scaling is needed, it would be:
            # ml_score = min(max(ml_score * SCALE_FACTOR, 0.0), 100.0)
            ml_score = min(max(ml_score, 0.0), 100.0)


            logger.debug(f"ML model predicted similarity for "
                        f"{folder1_info.path.name} vs {folder2_info.path.name}: {ml_score:.4f}")
            return ml_score
        except Exception as e:
            logger.error(f"Error during ML model prediction for "
                         f"{folder1_info.path.name} vs {folder2_info.path.name}: {e}", exc_info=True)
            return None
